/**
 * Read-only access to the bundled Zhouyi text.
 *
 * The JSON is generated by scripts/build-data.mjs from public-domain
 * transcriptions; see docs/SOURCES.md for provenance and corrections.
 */
import { readFileSync } from 'node:fs'

const DATA_URL = new URL('./hexagrams.json', import.meta.url)

export const DATASET = JSON.parse(readFileSync(DATA_URL, 'utf8'))
export const HEXAGRAMS = DATASET.hexagrams
export const BY_NUMBER = new Map(HEXAGRAMS.map((h) => [h.number, h]))
export const BY_BITS = new Map(HEXAGRAMS.map((h) => [h.bits.join(''), h]))

const TRIGRAM_READING = {
  乾: '乾', 兑: '兑', 离: '离', 震: '震', 巽: '巽', 坎: '坎', 艮: '艮', 坤: '坤',
}

export function hexagramOf(bits) {
  const key = bits.map((b) => (b ? 1 : 0)).join('')
  const found = BY_BITS.get(key)
  if (!found) throw new Error(`no hexagram for bits ${key}`)
  return found
}

export function hexagramByNumber(n) {
  const found = BY_NUMBER.get(Number(n))
  if (!found) throw new Error(`no hexagram numbered ${n}`)
  return found
}

/** 互卦：二三四爻为下卦，三四五爻为上卦。 */
export function nuclearBits(bits) {
  return [bits[1], bits[2], bits[3], bits[2], bits[3], bits[4]]
}

/** 错卦：六爻全变。 */
export function oppositeBits(bits) {
  return bits.map((b) => (b ? 0 : 1))
}

/** 综卦：全卦倒转。 */
export function inverseBits(bits) {
  return [...bits].reverse()
}

const ALIASES = {
  习坎: '坎', 遁: '遯', 兌: '兑', 頤: '颐', 噬嗑: '噬嗑',
}

/** Parse a user-facing query: number, name, full name, symbol, or 6-bit code. */
export function findHexagram(query) {
  if (query == null) return undefined
  let q = String(query).trim()
  if (!q) return undefined

  if (/^[\u4dc0-\u4dff]$/.test(q)) return HEXAGRAMS.find((h) => h.symbol === q)

  const digits = q.replace(/[^01]/g, '')
  if (/^[01\s|.|·-]{6,}$/.test(q) && digits.length === 6) {
    return BY_BITS.get(digits)
  }

  const num = q.match(/^(?:第)?\s*(\d{1,2})\s*卦?$/)
  if (num) {
    const n = Number(num[1])
    if (n >= 1 && n <= 64) return BY_NUMBER.get(n)
  }

  q = q.replace(/^第/, '').replace(/\s+/g, '').replace(/卦$/, '')
  const direct = HEXAGRAMS.find((h) => h.name === q || h.fullName === q || q === `${h.name}卦`)
  if (direct) return direct
  const alias = ALIASES[q]
  if (alias) return HEXAGRAMS.find((h) => h.name === alias)
  return undefined
}

export function trigramLine(h) {
  return `${TRIGRAM_READING[h.upper.name]}上${TRIGRAM_READING[h.lower.name]}下`
}

export function hexagramLabel(h) {
  return `第${h.number}卦　${h.fullName}　${h.symbol}（${trigramLine(h)}）`
}
